func withListQuery(endpoint string, params *ListRegistryParams) (string, error) {
	parsed, err := url.Parse(endpoint)
	if err != nil {
		return "", err
	}
	if params == nil {
		return parsed.String(), nil
	}
	query := parsed.Query()
	if params.Limit != nil {
		query.Set("limit", fmt.Sprintf("%d", *params.Limit))
	}
	if params.Cursor != "" {
		query.Set("cursor", params.Cursor)
	}
	parsed.RawQuery = query.Encode()
	return parsed.String(), nil
}

func doJSON[T any](ctx context.Context, client HTTPClient, method, endpoint, csrfToken string, body []byte) (*Response[T], error) {
	req, err := http.NewRequestWithContext(ctx, method, endpoint, bytes.NewReader(body))
	if err != nil {
		return nil, err
	}
	req.Header.Set("Accept", "application/json, application/problem+json")
	if csrfToken != "" {
		req.Header.Set("X-CSRF-Token", csrfToken)
	}
	httpResponse, err := client.Do(req)
	if err != nil {
		return nil, fmt.Errorf("call platform Gateway: %w", err)
	}
	payload, err := io.ReadAll(io.LimitReader(httpResponse.Body, 1<<20))
	_ = httpResponse.Body.Close()
	if err != nil {
		return nil, err
	}
	response := &Response[T]{
		StatusCode:          httpResponse.StatusCode,
		RequestID:           httpResponse.Header.Get("X-Request-ID"),
		Traceparent:         httpResponse.Header.Get("traceparent"),
		AuditMessageID:      httpResponse.Header.Get("X-Audit-Message-ID"),
		RoutePolicyRevision: httpResponse.Header.Get("X-Route-Policy-Revision"),
		HTTPResponse:        httpResponse,
	}
	if httpResponse.StatusCode >= 200 && httpResponse.StatusCode < 300 {
		if httpResponse.StatusCode == http.StatusNoContent {
			var zero T
			response.Data = &zero
			return response, nil
		}
		var data T
		if err := json.Unmarshal(payload, &data); err != nil {
			return nil, fmt.Errorf("decode platform Gateway success response: %w", err)
		}
		response.Data = &data
		return response, nil
	}
	var problem ProblemDetails
	if err := json.Unmarshal(payload, &problem); err != nil {
		return nil, fmt.Errorf("decode platform Gateway problem response: %w", err)
	}
	response.Problem = &problem
	return response, nil
}
